:root {
  --goo: #b8ff3d;
  --goo-soft: #d8ffa0;
  --goo-deep: #5fd21f;
  --teal: #2ce8c5;
  --pink: #ff3d81;
  --gold: #ffd75a;
  --ink: #05070f;
  --ink-2: #0b111c;
  --text: #e8f4e9;
  --muted: #93a99a;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --display: "Arial Black", "Inter", -apple-system, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: var(--font);
  overscroll-behavior: none;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

body { position: fixed; inset: 0; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #05070f;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

#vignette {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background:
    radial-gradient(ellipse 120% 90% at 50% 46%, rgba(0,0,0,0) 42%, rgba(0,0,0,.34) 78%, rgba(0,0,0,.66) 100%),
    linear-gradient(180deg, rgba(0,0,0,.28), rgba(0,0,0,0) 22%, rgba(0,0,0,0) 70%, rgba(0,0,0,.38));
}

#damageFlash, #gooFlash {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  opacity: 0;
}
#damageFlash { background: radial-gradient(circle at 50% 55%, rgba(255,40,90,.05) 30%, rgba(255,20,70,.6) 100%); }
#gooFlash { background: radial-gradient(circle at 50% 55%, rgba(190,255,100,.02) 25%, rgba(140,255,60,.45) 100%); }

@keyframes dmgFlash {
  0% { opacity: .95; }
  100% { opacity: 0; }
}
#damageFlash.on { animation: dmgFlash .55s ease-out forwards; }
#gooFlash.on { animation: dmgFlash .7s ease-out forwards; }

.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

/* ============================ HUD ============================ */
#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  transition: opacity .25s ease;
}

.hud-top {
  position: absolute;
  top: calc(var(--safe-t) + 12px);
  left: calc(var(--safe-l) + 16px);
  right: calc(var(--safe-r) + 16px);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 8px;
}

.score-block { justify-self: start; line-height: 1; }
.eyebrow {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .26em;
  color: rgba(214,255,180,.66);
  margin-bottom: 3px;
}
.score-value {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(30px, 7.4vw, 46px);
  letter-spacing: -.02em;
  color: #f0ffe0;
  text-shadow: 0 0 18px rgba(184,255,61,.45), 0 3px 0 rgba(0,0,0,.35);
  font-variant-numeric: tabular-nums;
  transition: transform .08s ease;
}
.score-value.bump { transform: scale(1.08); }
.best-inline {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .16em;
  color: rgba(214,255,180,.42);
  margin-top: 5px;
}

.hearts {
  display: flex;
  gap: 5px;
  justify-self: center;
  padding-top: 2px;
}
.heart {
  width: clamp(22px, 6.2vw, 30px);
  height: clamp(22px, 6.2vw, 30px);
  position: relative;
  transition: transform .18s cubic-bezier(.2,1.6,.4,1), opacity .2s;
  filter: drop-shadow(0 0 10px rgba(184,255,61,.6));
}
.heart svg { display: block; width: 100%; height: 100%; }
.heart .fill { fill: var(--goo); }
.heart .rim { fill: none; stroke: rgba(255,255,255,.35); stroke-width: 1.2; }
.heart.empty { opacity: .26; filter: none; }
.heart.empty .fill { fill: #38443c; }
.heart.pop { transform: scale(1.35); }
.heart.lost { animation: heartLost .5s ease-out; }
@keyframes heartLost {
  0% { transform: scale(1.6) rotate(-8deg); }
  40% { transform: scale(.8) rotate(6deg); opacity: .8; }
  100% { transform: scale(1); }
}

.hud-right {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 8px;
}
.wave-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  padding: 0 11px;
  border-radius: 999px;
  background: rgba(12,20,26,.56);
  border: 1px solid rgba(44,232,197,.22);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .16em;
  color: rgba(206,255,244,.72);
  white-space: nowrap;
}
.wave-chip b { color: var(--teal); font-size: 13px; letter-spacing: .05em; }
.wave-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 10px var(--teal);
  animation: wavepulse 1.6s infinite ease-in-out;
}
@keyframes wavepulse { 50% { opacity: .35; transform: scale(.75); } }

.icon-btn {
  width: 40px; height: 40px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(12,20,26,.56);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: rgba(232,244,233,.75);
  display: grid;
  place-items: center;
  pointer-events: auto;
  cursor: pointer;
  padding: 0;
  transition: transform .12s, background .2s;
}
.icon-btn:active { transform: scale(.92); background: rgba(30,44,36,.8); }

.combo {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 138px);
  transform: translate(-50%, 14px) scale(.8);
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0;
  transition: opacity .18s ease, transform .18s cubic-bezier(.2,1.7,.4,1);
  pointer-events: none;
  z-index: 12;
}
.combo.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.combo.pulse #comboMult { animation: comboPulse .3s cubic-bezier(.2,1.8,.4,1); }
#comboMult {
  font-family: var(--display);
  font-weight: 900;
  font-size: 34px;
  line-height: 1;
  color: var(--gold);
  text-shadow: 0 0 22px rgba(255,215,90,.7), 0 3px 0 rgba(0,0,0,.4);
}
.combo-label {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .38em;
  color: rgba(255,232,170,.8);
  margin-top: 3px;
  margin-left: .38em;
}
@keyframes comboPulse { 0% { transform: scale(1.45); } 100% { transform: scale(1); } }

.announce {
  position: absolute;
  left: 50%;
  top: 27%;
  transform: translate(-50%, 8px);
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(28px, 8vw, 52px);
  letter-spacing: .04em;
  color: #f4ffe6;
  text-shadow: 0 0 28px rgba(184,255,61,.55), 0 4px 0 rgba(0,0,0,.35);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
  z-index: 12;
  transition: opacity .2s ease, transform .3s cubic-bezier(.2,1.5,.4,1);
}
.announce.show { opacity: 1; transform: translate(-50%, 0); }
.announce.danger { color: #ffdce6; text-shadow: 0 0 30px rgba(255,61,129,.75), 0 4px 0 rgba(0,0,0,.35); }

/* ============================ CONTROLS ============================ */
#controls {
  position: absolute;
  inset: 0;
  z-index: 11;
  pointer-events: none;
  transition: opacity .25s ease;
}

.stick-ghost {
  position: absolute;
  left: calc(var(--safe-l) + 24px);
  bottom: calc(var(--safe-b) + 24px);
  width: 116px;
  height: 116px;
  border-radius: 50%;
  border: 1.5px dashed rgba(184,255,61,.22);
  background: radial-gradient(circle, rgba(184,255,61,.06), rgba(184,255,61,0) 70%);
  display: grid;
  place-items: center;
  transition: opacity .2s;
}
.stick-label {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .32em;
  margin-left: .32em;
  color: rgba(196,255,150,.35);
}

.stick {
  position: absolute;
  width: 124px;
  height: 124px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  border: 2px solid rgba(184,255,61,.35);
  background: radial-gradient(circle, rgba(140,255,70,.12), rgba(140,255,70,.02) 65%, rgba(0,0,0,0) 72%);
  box-shadow: 0 0 40px rgba(120,255,60,.12) inset;
  opacity: 0;
  transition: opacity .13s ease;
  pointer-events: none;
}
.stick.active { opacity: 1; }
.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 54px;
  height: 54px;
  margin: -27px 0 0 -27px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #eaffbd, #a9ff3f 45%, #63c526 100%);
  box-shadow: 0 4px 20px rgba(140,255,60,.5), 0 2px 0 rgba(255,255,255,.35) inset;
  will-change: transform;
}

.dash-btn {
  position: absolute;
  right: calc(var(--safe-r) + 24px);
  bottom: calc(var(--safe-b) + 24px);
  width: 96px;
  height: 96px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.24);
  background: radial-gradient(circle at 34% 28%, #f2ffc9, #b8ff3d 38%, #74d321 72%, #469a13 100%);
  color: #0b1a05;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  pointer-events: auto;
  cursor: pointer;
  touch-action: none;
  box-shadow: 0 10px 34px rgba(150,255,60,.32), 0 0 0 6px rgba(150,255,60,.07);
  transition: transform .09s ease, filter .2s, box-shadow .2s;
}
.dash-btn:active, .dash-btn.pressed { transform: scale(.93); box-shadow: 0 4px 16px rgba(150,255,60,.25), 0 0 0 4px rgba(150,255,60,.12); }
.dash-btn.no-charge { filter: grayscale(.65) brightness(.62); box-shadow: none; }
.dash-btn .dash-icon { display: block; margin-top: 3px; filter: drop-shadow(0 1px 0 rgba(255,255,255,.35)); }
.dash-label {
  font-family: var(--display);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .18em;
  margin-left: .18em;
}
.dash-pips { display: flex; gap: 3px; margin-top: 2px; }
.dash-pips i {
  width: 5px; height: 5px; border-radius: 50%;
  background: #10240a;
  opacity: .3;
  transition: opacity .15s, transform .15s, box-shadow .15s;
}
.dash-pips i.on { opacity: 1; background: #10240a; transform: scale(1.15); }
.dash-btn.no-charge .dash-pips i { background: #2a3328; }

/* ============================ SCREENS ============================ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  transition: opacity .3s ease, visibility .3s;
}

.title-screen {
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4,7,15,.92) 0%, rgba(4,7,15,.55) 20%, rgba(4,7,15,0) 38%, rgba(4,7,15,0) 58%, rgba(4,7,15,.72) 82%, rgba(4,7,15,.94) 100%);
}

.title-inner {
  position: absolute;
  inset: 0;
  padding: calc(var(--safe-t) + 22px) calc(var(--safe-r) + 22px) calc(var(--safe-b) + 22px) calc(var(--safe-l) + 22px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
}

.title-top { text-align: center; display: flex; flex-direction: column; align-items: center; }
.brandline {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .3em;
  color: rgba(202,255,170,.55);
  margin-bottom: 14px;
}
.brand-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--goo);
  box-shadow: 0 0 12px var(--goo);
}

.logo {
  position: relative;
  margin: 0;
  line-height: .82;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(60px, 17.2vw, 138px);
  letter-spacing: -.045em;
  transform: rotate(-2deg);
}
.logo-text {
  display: block;
  background: linear-gradient(178deg, #f4ffd9 4%, #c6ff6b 36%, #8bff2e 62%, #41c62b 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-stroke: 2px rgba(12,30,6,.55);
  filter: drop-shadow(0 0 34px rgba(160,255,60,.4)) drop-shadow(0 10px 22px rgba(0,0,0,.55));
}
.logo-drips {
  position: absolute;
  left: 6%;
  bottom: -24px;
  width: 88%;
  height: 40px;
  color: #8bff2e;
  filter: drop-shadow(0 6px 16px rgba(120,255,40,.3));
}
.logo::after {
  content: "";
  position: absolute;
  inset: -30% -10%;
  background: radial-gradient(ellipse at 50% 45%, rgba(140,255,60,.16), rgba(140,255,60,0) 62%);
  pointer-events: none;
  z-index: -1;
}
@keyframes logoBreathe {
  0%,100% { transform: rotate(-2deg) scale(1); }
  50% { transform: rotate(-1.4deg) scale(1.015); }
}
.logo { animation: logoBreathe 5.5s ease-in-out infinite; }

.tagline {
  margin: 30px 0 0;
  font-size: clamp(13px, 3.7vw, 17px);
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: .005em;
  color: rgba(226,244,222,.78);
  text-shadow: 0 2px 16px rgba(0,0,0,.7);
}

.title-bottom {
  width: min(360px, 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.btn {
  pointer-events: auto;
  border: 0;
  cursor: pointer;
  font-family: var(--display);
  font-weight: 900;
  letter-spacing: .1em;
  font-size: 17px;
  border-radius: 999px;
  transition: transform .1s ease, box-shadow .2s, filter .2s;
  touch-action: manipulation;
}
.btn-primary {
  width: 100%;
  height: 62px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #0a1603;
  background: linear-gradient(180deg, #dcff9e 0%, #b8ff3d 42%, #85e52b 100%);
  box-shadow: 0 14px 38px rgba(145,255,60,.32), 0 2px 0 rgba(255,255,255,.5) inset, 0 -3px 0 rgba(50,120,10,.35) inset;
}
.btn-primary:active { transform: scale(.97); box-shadow: 0 6px 18px rgba(145,255,60,.24), 0 2px 0 rgba(255,255,255,.4) inset; }
.btn-primary:hover { filter: brightness(1.05); }

.best-row {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .24em;
  color: rgba(200,230,190,.5);
}
.best-row b { color: var(--goo-soft); font-size: 13px; letter-spacing: .06em; }

.howto {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 2px;
}
.howto-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 600;
  color: rgba(205,228,203,.62);
  letter-spacing: .02em;
}
.key {
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .13em;
  padding: 4px 7px;
  border-radius: 7px;
  border: 1px solid rgba(184,255,61,.25);
  color: rgba(214,255,175,.85);
  background: rgba(30,48,22,.4);
}
.desktop-only { display: none; }
@media (hover: hover) and (pointer: fine) {
  .desktop-only { display: flex; }
}

.title-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 2px;
  font-size: 8px;
  letter-spacing: .12em;
  color: rgba(190,214,188,.35);
  text-transform: uppercase;
  font-weight: 700;
}
.dot-sep { opacity: .4; }
.text-btn {
  pointer-events: auto;
  background: none;
  border: 0;
  color: rgba(196,230,190,.65);
  font-family: var(--font);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .15em;
  padding: 4px;
  cursor: pointer;
  transition: color .15s;
}
.text-btn:hover { color: var(--goo-soft); }

/* ============================ OVERLAY PANELS ============================ */
.overlay-screen {
  display: grid;
  place-items: center;
  padding: calc(var(--safe-t) + 18px) 18px calc(var(--safe-b) + 18px);
  background: radial-gradient(ellipse at 50% 50%, rgba(6,12,14,.4), rgba(3,5,10,.82));
  backdrop-filter: blur(9px) saturate(.9);
  -webkit-backdrop-filter: blur(9px) saturate(.9);
}
.panel {
