}
.panel-sub {
  font-size: 12px;
  color: rgba(200,222,198,.55);
  margin: 8px 0 0;
}
.panel-buttons {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 20px;
}
.btn-ghost {
  width: 100%;
  height: 50px;
  color: rgba(222,244,216,.8);
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.12);
}
.btn-ghost:active { transform: scale(.98); background: rgba(255,255,255,.08); }
.panel-row {
  display: flex;
  justify-content: center;
  gap: 24px;
  margin-top: 4px;
}

.result-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 18px;
}
.result {
  border-radius: 16px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.06);
  padding: 10px 6px 9px;
}
.result span {
  display: block;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .24em;
  color: rgba(190,215,190,.45);
  margin-bottom: 3px;
}
.result b {
  font-family: var(--display);
  font-size: 24px;
  letter-spacing: -.01em;
  color: #f0ffe2;
  font-variant-numeric: tabular-nums;
}
.splat-mark {
  color: var(--pink);
  filter: drop-shadow(0 0 26px rgba(255,61,129,.45));
  margin: -6px auto 4px;
  width: 86px;
  height: 86px;
  animation: splatIn .5s cubic-bezier(.2,1.7,.4,1);
}
@keyframes splatIn {
  0% { transform: scale(.5) rotate(-16deg); opacity: 0; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
.new-best {
  margin-top: 12px;
  display: inline-block;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .2em;
  color: #08130a;
  background: var(--gold);
  padding: 6px 14px;
  border-radius: 999px;
  box-shadow: 0 0 26px rgba(255,215,90,.4);
  animation: newBestPulse 1.2s ease-in-out infinite;
}
@keyframes newBestPulse { 50% { transform: scale(1.06); } }

.rotate-hint {
  position: absolute;
  z-index: 60;
  left: 50%;
  bottom: calc(var(--safe-b) + 16px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
