  font-size: 10px;
  color: rgba(210,230,210,.65);
  white-space: nowrap;
}
.rotate-hint p { margin: 0; }
.rotate-icon { font-size: 14px; color: var(--goo); }

/* ============================ RESPONSIVE ============================ */
@media (max-width: 360px) {
