export class Sfx {
  constructor(){
    this.ctx = null;
    this.master = null;
    this.muted = localStorage.getItem('gooning:muted') === '1';
  }
  init(){
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    // compressor?
  }
  setMuted(m){...master.gain.setTargetAtTime(...)}
  _tone(freq, dur, {type='sine', gain=.2, slide=null, delay=0, attack=.005}={}) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(1,slide), t+dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t+attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t+dur+.02);
  }
  _noise(dur, {gain=.2, from=1200,to=200,type='lowpass',delay=0}={}) {...}
