import * as THREE from '../vendor/three.module.js';

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rnd = (a = 0, b = 1) => a + Math.random() * (b - a);
export const rndInt = (a, b) => Math.floor(rnd(a, b + 1));
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeOutBack = (t) => {
  const c1 = 1.70158, c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};

let _glowTex = null;
export function glowTexture() {
  if (_glowTex) return _glowTex;
  const size = 128;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.18, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.45, 'rgba(255,255,255,0.32)');
  g.addColorStop(0.72, 'rgba(255,255,255,0.08)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  _glowTex = new THREE.CanvasTexture(c);
  _glowTex.colorSpace = THREE.SRGBColorSpace;
  return _glowTex;
}

let _softTex = null;
export function softTexture() {
  if (_softTex) return _softTex;
  const size = 64;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.75, 'rgba(255,255,255,0.18)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  _softTex = new THREE.CanvasTexture(c);
  _softTex.colorSpace = THREE.SRGBColorSpace;
  return _softTex;
}

export function makeArenaTexture() {
  const size = 1024;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');

  // base
  const bg = ctx.createRadialGradient(size * 0.5, size * 0.46, size * 0.05, size * 0.5, size * 0.5, size * 0.55);
  bg.addColorStop(0, '#14322c');
  bg.addColorStop(0.45, '#0f2a26');
  bg.addColorStop(0.8, '#0a1d1d');
  bg.addColorStop(1, '#071317');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, size, size);

  // mottled goo stains
  for (let i = 0; i < 460; i++) {
    const a = Math.random() * TAU;
    const r = Math.sqrt(Math.random()) * size * 0.49;
    const x = size / 2 + Math.cos(a) * r;
    const y = size / 2 + Math.sin(a) * r;
    const rad = 6 + Math.random() * 54;
    const g = ctx.createRadialGradient(x, y, 0, x, y, rad);
    const hue = 120 + Math.random() * 50;
    const light = 12 + Math.random() * 18;
    const flip = Math.random();
    const col = flip > 0.55 ? `hsla(${hue}, 55%, ${light}%, 0.30)` : `hsla(190, 40%, ${light}%, 0.20)`;
    g.addColorStop(0, col);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, TAU);
    ctx.fill();
  }

  // concentric ritual rings
  ctx.strokeStyle = 'rgba(80,255,170,0.10)';
  for (const rr of [0.16, 0.32, 0.45, 0.475]) {
    ctx.lineWidth = rr > 0.46 ? 3 : 2;
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size * rr, 0, TAU);
    ctx.stroke();
  }
  // tick marks on outer ring
  ctx.strokeStyle = 'rgba(100,255,180,0.14)';
  ctx.lineWidth = 3;
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * TAU;
    const r1 = size * 0.468;
    const r2 = size * (i % 4 === 0 ? 0.485 : 0.478);
    ctx.beginPath();
    ctx.moveTo(size / 2 + Math.cos(a) * r1, size / 2 + Math.sin(a) * r1);
    ctx.lineTo(size / 2 + Math.cos(a) * r2, size / 2 + Math.sin(a) * r2);
    ctx.stroke();
  }

  // bright center pad
  const pad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size * 0.09);
  pad.addColorStop(0, 'rgba(150,255,110,0.20)');
  pad.addColorStop(0.7, 'rgba(120,255,140,0.05)');
  pad.addColorStop(1, 'rgba(120,255,140,0)');
  ctx.fillStyle = pad;
  ctx.fillRect(0, 0, size, size);

  // speckles
  for (let i = 0; i < 900; i++) {
    const a = Math.random() * TAU;
    const r = Math.sqrt(Math.random()) * size * 0.49;
    ctx.fillStyle = `rgba(180,255,200,${0.02 + Math.random() * 0.07})`;
    ctx.fillRect(size / 2 + Math.cos(a) * r, size / 2 + Math.sin(a) * r, 1.5, 1.5);
  }

  // dark rim vignette
  const rim = ctx.createRadialGradient(size / 2, size / 2, size * 0.36, size / 2, size / 2, size * 0.5);
  rim.addColorStop(0, 'rgba(0,0,0,0)');
  rim.addColorStop(1, 'rgba(0,0,0,0.72)');
  ctx.fillStyle = rim;
  ctx.fillRect(0, 0, size, size);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

export function makeTextSprite(text, opts = {}) {
  const {
    fontSize = 64,
    color = '#ffffff',
    weight = 900,
    font = 'Arial Black, Arial, sans-serif',
    padding = 24,
  } = opts;
  const c = document.createElement('canvas');
  const ctx = c.getContext('2d');
  ctx.font = `${weight} ${fontSize}px ${font}`;
  const w = Math.ceil(ctx.measureText(text).width + padding * 2);
  const h = fontSize + padding * 2;
  c.width = w;
  c.height = h;
  const ctx2 = c.getContext('2d');
  ctx2.font = `${weight} ${fontSize}px ${font}`;
  ctx2.textAlign = 'center';
  ctx2.textBaseline = 'middle';
  ctx2.fillStyle = color;
  ctx2.shadowColor = color;
  ctx2.shadowBlur = fontSize * 0.35;
  ctx2.fillText(text, w / 2, h / 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(w / h * 1.2, 1.2, 1);
  return sprite;
}

const MUTE_KEY = 'gooning.muted';

export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.muted = false;
    try { this.muted = localStorage.getItem(MUTE_KEY) === '1'; } catch (e) { /* ignore */ }
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 20;
    comp.ratio.value = 8;
    comp.attack.value = 0.004;
    comp.release.value = 0.22;
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    comp.connect(this.master);
    this.master.connect(this.ctx.destination);

    // shared noise buffer
    const len = Math.floor(this.ctx.sampleRate * 1.2);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
    this.bus = comp;
  }

  resume() {
    this.init();
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setMuted(m) {
    this.muted = !!m;
    try { localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0'); } catch (e) { /* ignore */ }
    if (this.master && this.ctx) {
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.linearRampToValueAtTime(this.muted ? 0 : 0.5, t + 0.12);
    }
  }

  tone({ freq = 440, to = null, type = 'sine', dur = 0.2, vol = 0.2, delay = 0, attack = 0.006 }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (to !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    g.connect(this.bus || this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.06);
  }

  noise({ dur = 0.25, vol = 0.25, from = 2400, to = 300, q = 1.2, type = 'lowpass', delay = 0 }) {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filt = this.ctx.createBiquadFilter();
    filt.type = type;
    filt.Q.value = q;
    filt.frequency.setValueAtTime(from, t0);
    filt.frequency.exponentialRampToValueAtTime(Math.max(40, to), t0 + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filt);
    filt.connect(g);
    g.connect(this.bus || this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.03);
  }

  click() {
    this.init();
    this.tone({ freq: 620, to: 880, type: 'triangle', dur: 0.07, vol: 0.12 });
  }

  pickup(step = 0) {
    const semis = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];
    const st = semis[Math.min(step, semis.length - 1)];
    const f = 523.25 * Math.pow(2, st / 12);
    this.tone({ freq: f, to: f * 1.02, type: 'triangle', dur: 0.14, vol: 0.16 });
    this.tone({ freq: f * 2, to: f * 2.04, type: 'sine', dur: 0.1, vol: 0.07, delay: 0.012 });
  }

  mega() {
    this.init();
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5];
    notes.forEach((f, i) => {
      this.tone({ freq: f, type: 'triangle', dur: 0.22, vol: 0.14, delay: i * 0.055 });
      this.tone({ freq: f * 2, type: 'sine', dur: 0.16, vol: 0.05, delay: i * 0.055 + 0.01 });
    });
    this.noise({ dur: 0.4, vol: 0.08, from: 6000, to: 2000, type: 'bandpass' });
  }

  dash() {
    this.init();
    this.noise({ dur: 0.22, vol: 0.22, from: 900, to: 3800, type: 'bandpass', q: 0.9 });
    this.tone({ freq: 180, to: 90, type: 'sawtooth', dur: 0.16, vol: 0.08 });
  }

  slam() {
    this.init();
    this.noise({ dur: 0.24, vol: 0.3, from: 1800, to: 160, type: 'lowpass', q: 0.7 });
    this.tone({ freq: 140, to: 54, type: 'square', dur: 0.2, vol: 0.16 });
    this.tone({ freq: 320, to: 90, type: 'triangle', dur: 0.12, vol: 0.08 });
  }

  hit() {
    this.init();
    this.noise({ dur: 0.32, vol: 0.36, from: 1200, to: 90, type: 'lowpass', q: 1 });
    this.tone({ freq: 110, to: 40, type: 'square', dur: 0.3, vol: 0.22 });
    this.tone({ freq: 220, to: 60, type: 'sawtooth', dur: 0.22, vol: 0.1 });
  }

  wave() {
    this.init();
    this.tone({ freq: 196, to: 196, type: 'sawtooth', dur: 0.26, vol: 0.1 });
    this.tone({ freq: 293.66, type: 'triangle', dur: 0.3, vol: 0.12, delay: 0.14 });
    this.tone({ freq: 392, type: 'triangle', dur: 0.34, vol: 0.1, delay: 0.28 });
  }

  refill() {
    this.tone({ freq: 880, to: 1320, type: 'sine', dur: 0.09, vol: 0.06 });
  }

  over() {
    this.init();
    const notes = [392, 329.63, 261.63, 196, 130.81];
    notes.forEach((f, i) => {
      this.tone({ freq: f, type: 'sawtooth', dur: 0.42, vol: 0.09, delay: i * 0.13 });
      this.tone({ freq: f / 2, type: 'sine', dur: 0.5, vol: 0.13, delay: i * 0.13 });
    });
    this.noise({ dur: 1.1, vol: 0.1, from: 900, to: 60, type: 'lowpass' });
  }
}

import * as THREE from '../vendor/three.module.js';
import { glowTexture, softTexture, rnd, TAU } from './util.js';

const MAX_PARTICLES = 700;
const MAX_RINGS = 18;
const MAX_SPLATS = 22;

export class FX {
  constructor(scene) {
    this.scene = scene;
    this.shake = 0;
    this.cursor = 0;
    this.time = 0;

    // ---------- particle points ----------
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(MAX_PARTICLES * 3);
    this.col = new Float32Array(MAX_PARTICLES * 3);
    this.siz = new Float32Array(MAX_PARTICLES);
    this.alp = new Float32Array(MAX_PARTICLES);
    this.vel = new Float32Array(MAX_PARTICLES * 3);
    this.life = new Float32Array(MAX_PARTICLES);
    this.maxLife = new Float32Array(MAX_PARTICLES);
    this.baseSize = new Float32Array(MAX_PARTICLES);
    this.drag = new Float32Array(MAX_PARTICLES);
    this.grav = new Float32Array(MAX_PARTICLES);

    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.siz, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alp, 1));

    const mat = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: softTexture() } },
      vertexShader: /* glsl */`
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (320.0 / max(0.1, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */`
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          float a = texture2D(uMap, gl_PointCoord).a;
          if (a < 0.01) discard;
          gl_FragColor = vec4(vColor, a * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });

    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
    scene.add(this.points);
    this.pgeo = geo;

    // ---------- rings ----------
    this.rings = [];
    const ringGeo = new THREE.RingGeometry(0.72, 1.0, 56);
    ringGeo.rotateX(-Math.PI / 2);
    for (let i = 0; i < MAX_RINGS; i++) {
      const m = new THREE.MeshBasicMaterial({
        color: 0xb8ff3d, transparent: true, opacity: 0, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      });
      const mesh = new THREE.Mesh(ringGeo, m);
      mesh.visible = false;
      mesh.renderOrder = 3;
      scene.add(mesh);
      this.rings.push({ mesh, mat: m, t: 0, dur: 1, from: 1, to: 4 });
    }
    this.ringCursor = 0;

    // ---------- splats ----------
    this.splats = [];
    const splatGeo = new THREE.PlaneGeometry(1, 1);
    splatGeo.rotateX(-Math.PI / 2);
    for (let i = 0; i < MAX_SPLATS; i++) {
      const m = new THREE.MeshBasicMaterial({
        map: softTexture(), color: 0x8bff2e, transparent: true, opacity: 0,
        depthWrite: false, toneMapped: false,
      });
      const mesh = new THREE.Mesh(splatGeo, m);
      mesh.visible = false;
      scene.add(mesh);
      this.splats.push({ mesh, mat: m, t: 0, dur: 4, size: 2 });
    }
    this.splatCursor = 0;

    this._c = new THREE.Color();
  }

  spawn(x, y, z, color, opts = {}) {
    const {
      count = 1, speed = 4, size = 0.8, life = 0.6, gravity = -9,
      up = 1.5, spread = 0.25, drag = 1.6, sizeVar = 0.4,
    } = opts;
    const c = this._c.set(color);
    for (let n = 0; n < count; n++) {
      let idx = -1;
      for (let k = 0; k < MAX_PARTICLES; k++) {
        const i = (this.cursor + k) % MAX_PARTICLES;
        if (this.life[i] <= 0) { idx = i; this.cursor = (i + 1) % MAX_PARTICLES; break; }
      }
      if (idx === -1) return;

      const i3 = idx * 3;
      this.pos[i3] = x + rnd(-spread, spread);
      this.pos[i3 + 1] = y + rnd(-spread * 0.6, spread * 0.6);
      this.pos[i3 + 2] = z + rnd(-spread, spread);

      const theta = Math.random() * TAU;
      const phi = Math.acos(rnd(-1, 1));
      const sp = speed * rnd(0.35, 1);
      this.vel[i3] = Math.sin(phi) * Math.cos(theta) * sp;
      this.vel[i3 + 1] = Math.abs(Math.cos(phi)) * sp * 0.35 + rnd(0.2, up);
      this.vel[i3 + 2] = Math.sin(phi) * Math.sin(theta) * sp;

      const tint = 0.82 + Math.random() * 0.35;
      this.col[i3] = Math.min(1, c.r * tint);
      this.col[i3 + 1] = Math.min(1, c.g * tint);
      this.col[i3 + 2] = Math.min(1, c.b * tint);

      const l = life * rnd(0.65, 1.25);
      this.life[idx] = l;
      this.maxLife[idx] = l;
      this.baseSize[idx] = size * rnd(1 - sizeVar, 1 + sizeVar);
      this.siz[idx] = this.baseSize[idx];
      this.alp[idx] = 1;
      this.grav[idx] = gravity;
      this.drag[idx] = drag;
    }
    this.pgeo.attributes.position.needsUpdate = true;
    this.pgeo.attributes.aColor.needsUpdate = true;
    this.pgeo.attributes.aSize.needsUpdate = true;
    this.pgeo.attributes.aAlpha.needsUpdate = true;
  }

  burst(x, y, z, color, opts = {}) {
    this.spawn(x, y, z, color, { count: 16, speed: 6.5, size: 1.1, life: 0.55, ...opts });
  }

  ring(x, z, color, { size = 5, dur = 0.55, y = 0.06, from = 0.5 } = {}) {
    const r = this.rings[this.ringCursor];
    this.ringCursor = (this.ringCursor + 1) % MAX_RINGS;
    r.mesh.position.set(x, y, z);
    r.mesh.visible = true;
    r.mat.color.set(color);
    r.mat.opacity = 0.85;
    r.t = 0;
    r.dur = dur;
    r.from = from;
    r.to = size;
    r.mesh.scale.setScalar(from);
  }

  splat(x, z, color = 0x7ee02a, size = 2.4) {
    const s = this.splats[this.splatCursor];
    this.splatCursor = (this.splatCursor + 1) % MAX_SPLATS;
    s.mesh.position.set(x, 0.035, z);
    s.mesh.rotation.y = Math.random() * TAU;
    s.mesh.scale.set(size, 1, size * rnd(0.75, 1.1));
    s.mat.color.set(color);
    s.mat.opacity = 0.42;
    s.mesh.visible = true;
    s.t = 0;
    s.dur = rnd(3.6, 5.4);
    s.size = size;
  }

  addShake(amount) {
    this.shake = Math.min(1.6, this.shake + amount);
  }

  update(dt) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 3.2);

    let any = false;
    for (let i = 0; i < MAX_PARTICLES; i++) {
      if (this.life[i] <= 0) continue;
      any = true;
      this.life[i] -= dt;
      const i3 = i * 3;
      if (this.life[i] <= 0) {
        this.alp[i] = 0;
        this.siz[i] = 0;
        continue;
      }
      const d = Math.exp(-this.drag[i] * dt);
      this.vel[i3] *= d;
      this.vel[i3 + 1] = this.vel[i3 + 1] * d + this.grav[i] * dt;
      this.vel[i3 + 2] *= d;
      this.pos[i3] += this.vel[i3] * dt;
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt;
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
      if (this.pos[i3 + 1] < 0.05) {
        this.pos[i3 + 1] = 0.05;
        this.vel[i3 + 1] *= -0.28;
      }
      const t = Math.max(0, this.life[i] / this.maxLife[i]);
      this.alp[i] = t * t;
      this.siz[i] = this.baseSize[i] * (0.35 + 0.75 * t);
    }
    if (any) {
      this.pgeo.attributes.position.needsUpdate = true;
      this.pgeo.attributes.aSize.needsUpdate = true;
      this.pgeo.attributes.aAlpha.needsUpdate = true;
    }

    for (const r of this.rings) {
      if (!r.mesh.visible) continue;
      r.t += dt;
      const k = Math.min(1, r.t / r.dur);
      const e = 1 - Math.pow(1 - k, 3);
      r.mesh.scale.setScalar(r.from + (r.to - r.from) * e);
      r.mat.opacity = 0.85 * (1 - k) * (1 - k);
      if (k >= 1) r.mesh.visible = false;
    }

    for (const s of this.splats) {
      if (!s.mesh.visible) continue;
      s.t += dt;
      const k = Math.min(1, s.t / s.dur);
      s.mat.opacity = 0.4 * (1 - k);
      if (k >= 1) s.mesh.visible = false;
    }
  }
}

