23:     comp.ratio.value = 8;
24:     comp.attack.value = 0.004;
25:     comp.release.value = 0.22;
26:     this.master = this.ctx.createGain();
27:     this.master.gain.value = this.muted ? 0 : 0.5;
28:     comp.connect(this.master);
29:     this.master.connect(this.ctx.destination);
30: 
31:     // shared noise buffer
32:     const len = Math.floor(this.ctx.sampleRate * 1.2);
33:     const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
34:     const data = buf.getChannelData(0);
35:     for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
36:     this.noiseBuffer = buf;
37:     this.bus = comp;
38:   }
39: 
40:   resume() {
41:     this.init();
42:     if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
43:   }
44: 
45:   setMuted(m) {
46:     this.muted = !!m;
47:     try { localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0'); } catch (e) { /* ignore */ }
48:     if (this.master && this.ctx) {
49:       const t = this.ctx.currentTime;
50:       this.master.gain.cancelScheduledValues(t);
51:       this.master.gain.linearRampToValueAtTime(this.muted ? 0 : 0.5, t + 0.12);
52:     }
53:   }
54: 
55:   tone({ freq = 440, to = null, type = 'sine', dur = 0.2, vol = 0.2, delay = 0, attack = 0.006 }) {
56:     if (!this.ctx || this.muted) return;
57:     const t0 = this.ctx.currentTime + delay;
58:     const osc = this.ctx.createOscillator();
59:     const g = this.ctx.createGain();
60:     osc.type = type;
61:     osc.frequency.setValueAtTime(Math.max(20, freq), t0);
62:     if (to !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
63:     g.gain.setValueAtTime(0.0001, t0);
64:     g.gain.linearRampToValueAtTime(vol, t0 + attack);
65:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
66:     osc.connect(g);
67:     g.connect(this.bus || this.master);
68:     osc.start(t0);
69:     osc.stop(t0 + dur + 0.06);
70:   }
71: 
72:   noise({ dur = 0.25, vol = 0.25, from = 2400, to = 300, q = 1.2, type = 'lowpass', delay = 0 }) {
73:     if (!this.ctx || this.muted || !this.noiseBuffer) return;
74:     const t0 = this.ctx.currentTime + delay;
75:     const src = this.ctx.createBufferSource();
76:     src.buffer = this.noiseBuffer;
77:     const filt = this.ctx.createBiquadFilter();
78:     filt.type = type;
79:     filt.Q.value = q;
80:     filt.frequency.setValueAtTime(from, t0);
81:     filt.frequency.exponentialRampToValueAtTime(Math.max(40, to), t0 + dur);
82:     const g = this.ctx.createGain();
83:     g.gain.setValueAtTime(0.0001, t0);
84:     g.gain.linearRampToValueAtTime(vol, t0 + 0.012);
85:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
86:     src.connect(filt);
87:     filt.connect(g);
88:     g.connect(this.bus || this.master);
89:     src.start(t0);
90:     src.stop(t0 + dur + 0.03);
91:   }
92: 
93:   click() {
94:     this.init();
95:     this.tone({ freq: 620, to: 880, type: 'triangle', dur: 0.07, vol: 0.12 });
96:   }
97: 
98:   pickup(step = 0) {
99:     const semis = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];
100:     const st = semis[Math.min(step, semis.length - 1)];
101:     const f = 523.25 * Math.pow(2, st / 12);
102:     this.tone({ freq: f, to: f * 1.02, type: 'triangle', dur: 0.14, vol: 0.16 });
103:     this.tone({ freq: f * 2, to: f * 2.04, type: 'sine', dur: 0.1, vol: 0.07, delay: 0.012 });
104:   }
105: 
106:   mega() {
107:     this.init();
108:     const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5];
109:     notes.forEach((f, i) => {
110:       this.tone({ freq: f, type: 'triangle', dur: 0.22, vol: 0.14, delay: i * 0.055 });
111:       this.tone({ freq: f * 2, type: 'sine', dur: 0.16, vol: 0.05, delay: i * 0.055 + 0.01 });
112:     });
113:     this.noise({ dur: 0.4, vol: 0.08, from: 6000, to: 2000, type: 'bandpass' });
114:   }
115: 
116:   dash() {
117:     this.init();
118:     this.noise({ dur: 0.22, vol: 0.22, from: 900, to: 3800, type: 'bandpass', q: 0.9 });
119:     this.tone({ freq: 180, to: 90, type: 'sawtooth', dur: 0.16, vol: 0.08 });
120:   }
121: 
122:   slam() {
123:     this.init();
124:     this.noise({ dur: 0.24, vol: 0.3, from: 1800, to: 160, type: 'lowpass', q: 0.7 });
125:     this.tone({ freq: 140, to: 54, type: 'square', dur: 0.2, vol: 0.16 });
126:     this.tone({ freq: 320, to: 90, type: 'triangle', dur: 0.12, vol: 0.08 });
127:   }
128: 
129:   hit() {
130:     this.init();
131:     this.noise({ dur: 0.32, vol: 0.36, from: 1200, to: 90, type: 'lowpass', q: 1 });
132:     this.tone({ freq: 110, to: 40, type: 'square', dur: 0.3, vol: 0.22 });
133:     this.tone({ freq: 220, to: 60, type: 'sawtooth', dur: 0.22, vol: 0.1 });
134:   }
135: 
136:   wave() {
137:     this.init();
138:     this.tone({ freq: 196, to: 196, type: 'sawtooth', dur: 0.26, vol: 0.1 });
139:     this.tone({ freq: 293.66, type: 'triangle', dur: 0.3, vol: 0.12, delay: 0.14 });
140:     this.tone({ freq: 392, type: 'triangle', dur: 0.34, vol: 0.1, delay: 0.28 });
141:   }
142: 
143:   refill() {
144:     this.tone({ freq: 880, to: 1320, type: 'sine', dur: 0.09, vol: 0.06 });
145:   }
146: 
147:   over() {
148:     this.init();
149:     const notes = [392, 329.63, 261.63, 196, 130.81];
150:     notes.forEach((f, i) => {
151:       this.tone({ freq: f, type: 'sawtooth', dur: 0.42, vol: 0.09, delay: i * 0.13 });
152:       this.tone({ freq: f / 2, type: 'sine', dur: 0.5, vol: 0.13, delay: i * 0.13 });
153:     });
154:     this.noise({ dur: 1.1, vol: 0.1, from: 900, to: 60, type: 'lowpass' });
155:   }
